def count_fires(spec: str, blackouts: list[tuple[int, int]], a: int, b: int) -> int:
    # --- Parse the spec ---
    fields = spec.split()
    if len(fields) != 3:
        raise ValueError("wrong number of fields")

    MAXES = [59, 23, 6]

    def _parse_term(term, max_val):
        # Split off optional /step
        if '/' in term:
            parts = term.split('/')
            if len(parts) != 2:
                raise ValueError("more than one /")
            base, step_str = parts
            if not step_str or not step_str.isdigit():
                raise ValueError("invalid step")
            step = int(step_str)
            if step < 1:
                raise ValueError("step of 0")
        else:
            base = term
            step = None

        if '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError("invalid range")
            n_str, m_str = parts
            if not n_str.isdigit() or not m_str.isdigit():
                raise ValueError("invalid number")
            n, m = int(n_str), int(m_str)
            if n > m:
                raise ValueError("N > M")
            if m > max_val:
                raise ValueError("value above MAX")
            if step is None:
                return set(range(n, m + 1))
            return set(range(n, m + 1, step))
        elif base == '*':
            if step is None:
                return set(range(max_val + 1))
            return set(range(0, max_val + 1, step))
        else:
            if not base.isdigit():
                raise ValueError("invalid number")
            n = int(base)
            if n > max_val:
                raise ValueError("value above MAX")
            if step is None:
                return {n}
            return set(range(n, max_val + 1, step))

    field_sets = []
    for i, field in enumerate(fields):
        terms = field.split(',')
        s = set()
        for term in terms:
            if not term:
                raise ValueError("empty term")
            s |= _parse_term(term, MAXES[i])
        field_sets.append(s)

    minutes, hours, weekdays = field_sets

    # Build the set of firing offsets within one 10080-minute week
    firing = set()
    for w in weekdays:
        for h in hours:
            for m in minutes:
                firing.add(w * 1440 + h * 60 + m)

    total_per_week = len(firing)
    WEEK = 10080

    # Prefix-sum array for O(1) range counting within a partial week
    is_firing = [0] * WEEK
    for f in firing:
        is_firing[f] = 1
    prefix = [0] * (WEEK + 1)
    for i in range(WEEK):
        prefix[i + 1] = prefix[i] + is_firing[i]

    if b <= a:
        return 0

    def count_in_range(lo, hi):
        """Count t in [lo, hi) with t % 10080 in firing."""
        length = hi - lo
        full = length // WEEK
        rem = length % WEEK
        cnt = full * total_per_week
        if rem:
            start = lo % WEEK
            end = start + rem  # exclusive end offset
            if end <= WEEK:
                cnt += prefix[end] - prefix[start]
            else:
                cnt += prefix[WEEK] - prefix[start] + prefix[end - WEEK]
        return cnt

    # Total without blackouts
    total = count_in_range(a, b)

    # Clip blackouts to [a, b), merge overlapping/touching ones
    intervals = []
    for s, e in blackouts:
        ns, ne = max(a, s), min(b, e)
        if ns < ne:
            intervals.append((ns, ne))

    if intervals:
        intervals.sort()
        merged = [intervals[0]]
        for s, e in intervals[1:]:
            if s <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], e))
            else:
                merged.append((s, e))

    for s, e in merged:
        total -= count_in_range(s, e)

    return total
