class FairQueue:
    WAITING = "WAITING"
    PAUSED = "PAUSED"
    RUNNING = "RUNNING"

    def __init__(self, aging, cap):
        self.aging = aging
        self.cap = cap
        self.jobs = {}
        self._seq = 0

    def _total_waited(self, name, t):
        j = self.jobs[name]
        return j["waited"] + (t - j["start"])

    def _effective_priority(self, name, t):
        j = self.jobs[name]
        return j["base"] + min(self.cap, self._total_waited(name, t) // self.aging)

    def _sort_key(self, name, t):
        tw = self._total_waited(name, t)
        ep = self._effective_priority(name, t)
        return (-ep, -tw, self.jobs[name]["seq"])

    def _finalize_waiting(self, name, t):
        j = self.jobs[name]
        j["waited"] += t - j["start"]

    def submit(self, job, priority, t):
        if job in self.jobs:
            raise ValueError(f"Job '{job}' already exists")
        self._seq += 1
        self.jobs[job] = {
            "state": self.WAITING,
            "base": priority,
            "waited": 0,
            "start": t,
            "seq": self._seq,
        }

    def start(self, t):
        waiting = [
            name for name, j in self.jobs.items() if j["state"] == self.WAITING
        ]
        if not waiting:
            return None
        waiting.sort(key=lambda n: self._sort_key(n, t))
        job = waiting[0]
        self._finalize_waiting(job, t)
        self.jobs[job]["state"] = self.RUNNING
        return job

    def finish(self, job, t):
        if job not in self.jobs:
            raise KeyError(job)
        if self.jobs[job]["state"] != self.RUNNING:
            raise KeyError(job)
        del self.jobs[job]

    def requeue(self, job, t):
        if job not in self.jobs:
            raise KeyError(job)
        if self.jobs[job]["state"] != self.RUNNING:
            raise KeyError(job)
        self._seq += 1
        j = self.jobs[job]
        j["base"] -= 1
        j["state"] = self.WAITING
        j["start"] = t
        j["seq"] = self._seq

    def pause(self, job, t):
        if job not in self.jobs:
            raise KeyError(job)
        j = self.jobs[job]
        if j["state"] == self.RUNNING:
            raise KeyError(job)
        if j["state"] == self.WAITING:
            self._finalize_waiting(job, t)
            j["state"] = self.PAUSED
            return True
        return False

    def resume(self, job, t):
        if job not in self.jobs:
            raise KeyError(job)
        j = self.jobs[job]
        if j["state"] == self.RUNNING:
            raise KeyError(job)
        if j["state"] == self.PAUSED:
            j["state"] = self.WAITING
            j["start"] = t
            return True
        return False

    def cancel(self, job):
        if job in self.jobs:
            del self.jobs[job]
            return True
        return False

    def queue(self, t):
        waiting = [
            name for name, j in self.jobs.items() if j["state"] == self.WAITING
        ]
        waiting.sort(key=lambda n: self._sort_key(n, t))
        return [(name, self._effective_priority(name, t)) for name in waiting]
