import heapq
from collections import defaultdict


def ferry_plan(routes: list[tuple[str, str, int, int, int]], src: str, dst: str, t0: int):
    if src == dst:
        return (t0, 0)

    # Build adjacency list, skipping useless self-loops
    adj: dict[str, list[tuple[str, int, int, int]]] = defaultdict(list)
    for a, b, first, every, duration in routes:
        if a != b:
            adj[a].append((b, first, every, duration))

    # best[port] = list of non-dominated (time, ferry_count) pairs for that port
    best: dict[str, list[tuple[int, int]]] = {}
    best[src] = [(t0, 0)]

    # Min-heap ordered lexicographically by (time, ferry_count, port)
    heap: list[tuple[int, int, str]] = [(t0, 0, src)]

    while heap:
        time, count, port = heapq.heappop(heap)

        # Staleness check: skip if a currently-best state for this port
        # strictly dominates this one.  (The state itself, if still in
        # best[port], is not a strict dominator of itself, so it's safe.)
        stale = False
        for (bt, bc) in best.get(port, []):
            if bt <= time and bc <= count and (bt < time or bc < count):
                stale = True
                break
        if stale:
            continue

        if port == dst:
            return (time, count)

        for b, first, every, duration in adj[port]:
            # Earliest departure at or after `time`
            if time <= first:
                depart = first
            else:
                k = (time - first + every - 1) // every
                depart = first + k * every

            arrive = depart + duration
            new_count = count + 1

            # Is (arrive, new_count) dominated by an existing best[b] entry?
            if b in best:
                dominated = False
                for (bt, bc) in best[b]:
                    if bt <= arrive and bc <= new_count and (bt < arrive or bc < new_count):
                        dominated = True
                        break
                if dominated:
                    continue
                # Drop entries from best[b] that the new state dominates.
                best[b] = [
                    (bt, bc)
                    for (bt, bc) in best[b]
                    if not (arrive <= bt and new_count <= bc and (arrive < bt or new_count < bc))
                ]
                best[b].append((arrive, new_count))
            else:
                best[b] = [(arrive, new_count)]

            heapq.heappush(heap, (arrive, new_count, b))

    return None
