from collections import defaultdict, deque


def last_link_times(n: int, cables: list[tuple[int, int, int]], pairs: list[tuple[int, int]]) -> list:
    if not pairs:
        return []

    # Step 1: Build maximum spanning forest via Kruskal (sort by failure desc)
    cables_sorted = sorted(cables, key=lambda x: x[2], reverse=True)

    dsu_parent = list(range(n))
    dsu_rank = [0] * n

    def find(x):
        while dsu_parent[x] != x:
            dsu_parent[x] = dsu_parent[dsu_parent[x]]
            x = dsu_parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if dsu_rank[ra] < dsu_rank[rb]:
            ra, rb = rb, ra
        dsu_parent[rb] = ra
        if dsu_rank[ra] == dsu_rank[rb]:
            dsu_rank[ra] += 1
        return True

    forest_edges = []
    for a, b, fail in cables_sorted:
        if a == b:
            continue
        if union(a, b):
            forest_edges.append((a, b, fail))

    # Step 2: Build adjacency list and run BFS from each root
    adj = defaultdict(list)
    for a, b, fail in forest_edges:
        adj[a].append((b, fail))
        adj[b].append((a, fail))

    visited = [False] * n
    depth = [0] * n
    parent_arr = list(range(n))          # root -> self
    min_to_parent = [float('inf')] * n   # edge weight to direct parent
    component = list(range(n))           # root-of-tree id per node

    for i in range(n):
        if not visited[i]:
            q = deque([i])
            visited[i] = True
            while q:
                node = q.popleft()
                for nb, w in adj[node]:
                    if not visited[nb]:
                        visited[nb] = True
                        depth[nb] = depth[node] + 1
                        parent_arr[nb] = node
                        min_to_parent[nb] = w
                        component[nb] = i
                        q.append(nb)

    # Step 3: Binary-lift tables
    LOG = n.bit_length() + 1
    up = [[0] * n for _ in range(LOG)]
    mn = [[float('inf')] * n for _ in range(LOG)]

    for node in range(n):
        up[0][node] = parent_arr[node]
        mn[0][node] = min_to_parent[node]

    for k in range(1, LOG):
        prev = up[k - 1]
        for node in range(n):
            mid = prev[node]
            up[k][node] = up[k - 1][mid]
            mn[k][node] = mn[k - 1][mid] if mn[k - 1][mid] < mn[k - 1][node] else mn[k - 1][node]

    # Step 4: Answer each pair query
    def query(u, v):
        if u == v:
            return None
        if component[u] != component[v]:
            return 0

        best = float('inf')
        if depth[u] < depth[v]:
            u, v = v, u
        # Lift deeper node up to the other's depth
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if diff >> k & 1:
                if mn[k][u] < best:
                    best = mn[k][u]
                u = up[k][u]
        if u == v:
            return best
        # Climb both until their parents coincide (LCA)
        for k in range(LOG - 1, -1, -1):
            if up[k][u] != up[k][v]:
                if mn[k][u] < best:
                    best = mn[k][u]
                if mn[k][v] < best:
                    best = mn[k][v]
                u = up[k][u]
                v = up[k][v]
        # One last hop to the LCA
        if mn[0][u] < best:
            best = mn[0][u]
        if mn[0][v] < best:
            best = mn[0][v]
        return best

    return [query(u, v) for u, v in pairs]
