class VaultKV:
    def __init__(self):
        self._data = {}
        self._lockset = set()
        self._holders = {}
        self._txn_stack = []

    # ---------- data methods ----------

    def put(self, key, value):
        if key in self._lockset:
            raise PermissionError(f"Key '{key}' is locked")
        old_value = self._data.get(key)
        if self._txn_stack:
            self._txn_stack[-1]['data_ops'].append((key, old_value, value))
        self._set_data_and_holders(key, old_value, value)

    def get(self, key, default=None):
        return self._data.get(key, default)

    def drop(self, key) -> bool:
        if key in self._lockset:
            raise PermissionError(f"Key '{key}' is locked")
        old_value = self._data.get(key)
        if old_value is None:
            return False
        if self._txn_stack:
            self._txn_stack[-1]['data_ops'].append((key, old_value, None))
        self._set_data_and_holders(key, old_value, None)
        return True

    def incr(self, key, by=1) -> int:
        if key in self._lockset:
            raise PermissionError(f"Key '{key}' is locked")
        old_value = self._data.get(key)
        if old_value is not None and isinstance(old_value, str):
            raise TypeError("Cannot incr a key whose value is a string")
        new_value = (0 if old_value is None else old_value) + by
        if self._txn_stack:
            self._txn_stack[-1]['data_ops'].append((key, old_value, new_value))
        self._set_data_and_holders(key, old_value, new_value)
        return new_value

    def holders(self, value) -> list:
        return sorted(self._holders.get(value, ()))

    def size(self) -> int:
        return len(self._data)

    # ---------- locks ----------

    def lock(self, key):
        if key not in self._lockset:
            self._lockset.add(key)
            if self._txn_stack:
                self._txn_stack[-1]['lock_ops'].append((key, False))

    def unlock(self, key):
        if key in self._lockset:
            self._lockset.discard(key)
            if self._txn_stack:
                self._txn_stack[-1]['lock_ops'].append((key, True))

    def locked(self, key) -> bool:
        return key in self._lockset

    # ---------- transactions ----------

    def begin(self, name=None):
        self._txn_stack.append({'name': name, 'data_ops': [], 'lock_ops': []})
        return len(self._txn_stack)

    def commit(self) -> int:
        if not self._txn_stack:
            raise RuntimeError("No open transaction")
        txn = self._txn_stack.pop()
        if self._txn_stack:
            parent = self._txn_stack[-1]
            parent['data_ops'].extend(txn['data_ops'])
            parent['lock_ops'].extend(txn['lock_ops'])
        return len(self._txn_stack)

    def rollback(self, name=None) -> int:
        if not self._txn_stack:
            raise RuntimeError("No open transaction")

        if name is None:
            idx = len(self._txn_stack) - 1
        else:
            idx = -1
            for i in range(len(self._txn_stack) - 1, -1, -1):
                if self._txn_stack[i]['name'] == name:
                    idx = i
                    break
            if idx == -1:
                raise KeyError(name)

        to_rollback = self._txn_stack[idx:]
        del self._txn_stack[idx:]

        # Collect undo ops in the correct order:
        # innermost transaction first, and within each txn, ops in reverse.
        undo_data = []
        undo_locks = []
        for txn in reversed(to_rollback):
            undo_data.extend(reversed(txn['data_ops']))
            undo_locks.extend(reversed(txn['lock_ops']))

        # Undo lock changes
        for key, was_locked in undo_locks:
            if was_locked:
                self._lockset.add(key)
            else:
                self._lockset.discard(key)

        # Undo data changes
        for key, old_value, new_value in undo_data:
            if new_value is not None:
                holders_set = self._holders[new_value]
                holders_set.discard(key)
                if not holders_set:
                    del self._holders[new_value]
                del self._data[key]
            if old_value is not None:
                self._data[key] = old_value
                if old_value not in self._holders:
                    self._holders[old_value] = set()
                self._holders[old_value].add(key)

        return len(self._txn_stack)

    def depth(self) -> int:
        return len(self._txn_stack)

    # ---------- internal helpers ----------

    def _set_data_and_holders(self, key, old_value, new_value):
        if old_value is not None:
            hs = self._holders[old_value]
            hs.discard(key)
            if not hs:
                del self._holders[old_value]
            del self._data[key]
        if new_value is not None:
            self._data[key] = new_value
            if new_value not in self._holders:
                self._holders[new_value] = set()
            self._holders[new_value].add(key)
