def resolve_profiles(text: str) -> dict:
    profiles = {}
    current_profile = None

    for raw_line in text.split("\n"):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        if line.startswith("[") and line.endswith("]"):
            inner = line[1:-1]
            if "<" in inner:
                name, rest = inner.split("<", 1)
                name = name.strip()
                parents = [p.strip() for p in rest.split(",")]
            else:
                name = inner.strip()
                parents = []

            if not name:
                raise ValueError("Empty profile name")
            for p in parents:
                if not p:
                    raise ValueError(f"Empty parent name: {p!r}")
            if name in profiles:
                raise ValueError(f"Duplicate profile name: {name!r}")

            profiles[name] = {"parents": parents, "operations": []}
            current_profile = name
        else:
            if current_profile is None:
                raise ValueError("Operation line before first header")

            if line.startswith("!"):
                key = line[1:].strip()
                if not key:
                    raise ValueError("Empty key for delete")
                profiles[current_profile]["operations"].append(("delete", key))
            else:
                eq_idx = line.find("=")
                if eq_idx == -1:
                    raise ValueError("No '=' found")

                if eq_idx >= 1 and line[eq_idx - 1] in ("+", "-"):
                    op = line[eq_idx - 1]
                    key = line[: eq_idx - 1].strip()
                else:
                    op = "="
                    key = line[: eq_idx].strip()

                if not key:
                    raise ValueError("Empty key")

                value_str = line[eq_idx + 1 :].strip()

                if op == "=":
                    profiles[current_profile]["operations"].append(("set", key, value_str))
                else:
                    items = [x.strip() for x in value_str.split(",")]
                    items = [x for x in items if x]
                    profiles[current_profile]["operations"].append(("add" if op == "+" else "remove", key, items))

    raw_maps = {}
    in_progress = set()

    def build_raw(name):
        if name in raw_maps:
            return raw_maps[name]
        if name not in profiles:
            raise ValueError(f"Unknown parent: {name!r}")
        if name in in_progress:
            raise ValueError(f"Inheritance cycle detected involving {name!r}")

        in_progress.add(name)
        raw = {}

        for parent in profiles[name]["parents"]:
            p_raw = build_raw(parent)
            for k, v in p_raw.items():
                raw[k] = list(v) if isinstance(v, list) else v

        for kind, *args in profiles[name]["operations"]:
            if kind == "delete":
                raw.pop(args[0], None)
            elif kind == "set":
                raw[args[0]] = args[1]
            elif kind == "add":
                key, items = args
                if key not in raw:
                    raw[key] = []
                else:
                    v = raw[key]
                    if isinstance(v, str):
                        raw[key] = [v]
                raw[key].extend(items)
            else:  # remove
                key, items = args
                if key not in raw:
                    continue
                v = raw[key]
                if isinstance(v, str):
                    raise ValueError(f"Cannot -= from string value {key!r}")
                for item in items:
                    while item in v:
                        v.remove(item)

        in_progress.discard(name)
        raw_maps[name] = raw
        return raw

    for name in profiles:
        build_raw(name)

    def interp(s, pname, seen):
        out = []
        i, n = 0, len(s)
        while i < n:
            c = s[i]
            if c == "$":
                if i + 1 < n and s[i + 1] == "$":
                    out.append("$")
                    i += 2
                elif i + 1 < n and s[i + 1] == "{":
                    close = s.find("}", i + 2)
                    if close == -1:
                        raise ValueError("Unclosed ${...}")
                    key = s[i + 2 : close]
                    i = close + 1
                    if key in seen:
                        raise ValueError(f"Circular reference to {key!r}")
                    if key not in raw_maps[pname]:
                        raise ValueError(f"Unknown key {key!r} in profile {pname!r}")
                    val = raw_maps[pname][key]
                    seen2 = seen | {key}
                    if isinstance(val, list):
                        out.append(",".join(interp(item, pname, seen2) for item in val))
                    else:
                        out.append(interp(val, pname, seen2))
                else:
                    raise ValueError(f"Invalid $ usage at position {i}")
            else:
                out.append(c)
                i += 1
        return "".join(out)

    def interp_profile(name):
        raw = raw_maps[name]
        return {
            k: (
                [interp(item, name, {k}) for item in v] if isinstance(v, list) else interp(v, name, {k})
            )
            for k, v in raw.items()
        }

    return {name: interp_profile(name) for name in profiles}
