        total = 0
        n_ring = len(ring)

        for mask in range(1, 1 << n_ring):
            L = 1
            for i in range(n_ring):
                if mask & (1 << i):
                    L = L * ring[i] // gcd(L, ring[i])

            N = x // L
            if N == 0:
                continue

            # If any muted number divides L, every multiple of L is muted → 0 contribution
            divisors = []
            skip = False
            for m in mute:
                if L % m == 0:
                    skip = True
                else:
                    g = gcd(L, m)
                    d = m // g
                    if d > 1:
                        divisors.append(d)

            if skip:
                continue

            # Inclusion-exclusion: count k in [1, N] divisible by at least one value in `divisors`
            div_count = 0
            n_div = len(divisors)
            for dmask in range(1, 1 << n_div):
                dL = 1
                for j in range(n_div):
                    if dmask & (1 << j):
                        dL = dL * divisors[j] // gcd(dL, divisors[j])
                rc = dmask.bit_count()
                sign = 1 if rc % 2 == 1 else -1
                div_count += sign * (N // dL)

            rc = mask.bit_count()
            sign = 1 if rc % 2 == 1 else -1
            total += sign * (N - div_count)

        return total

    # The chime pattern repeats every P. If no chime in one full period, none ever.
    if count_chimes(P) == 0:
        return None

    # Exponential search to find an upper bound
    high = 1
    while count_chimes(high) < k:
        high *= 2

    # Binary search for the k-th chime
    low = 1
    while low < high:
        mid = (low + high) // 2
        if count_chimes(mid) >= k:
            high = mid
        else:
            low = mid + 1

    return low
