from typing import Optional


def kth_arrangement(letters: str, k: int) -> Optional[str]:
    if k < 1:
        raise ValueError("k must be >= 1")

    n_letters = len(letters)
    unique_chars = sorted(set(letters))
    n = len(unique_chars)
    char_to_idx = {c: i for i, c in enumerate(unique_chars)}

    initial_counts = [0] * n
    for c in letters:
        initial_counts[char_to_idx[c]] += 1

    @lru_cache(maxsize=None)
    def dp(counts: tuple, last: int, first: int) -> int:
        """
        Count valid completions.
        counts: remaining count of each distinct character (tuple, hashable)
        last: index into unique_chars of last placed char, or -1 if none
        first: index into unique_chars of the first char of the arrangement, or -1 if none
        """
        remaining = sum(counts)

        if remaining == 0:
            if n_letters == 1:
                return 1
            return 1 if last != first else 0

        result = 0
        for i in range(n):
            if counts[i] > 0:
                if last == -1 or unique_chars[i] != unique_chars[last]:
                    new_counts = list(counts)
                    new_counts[i] -= 1
                    new_first = i if last == -1 else first
                    result += dp(tuple(new_counts), i, new_first)
        return result

    total_valid = dp(tuple(initial_counts), -1, -1)
    if total_valid < k:
        return None

    # Build the k-th arrangement character by character.
    result = []
    cur_counts = list(initial_counts)
    last = -1
    first = -1

    for _ in range(n_letters):
        for i in range(n):
            if cur_counts[i] > 0 and (last == -1 or unique_chars[i] != unique_chars[last]):
                new_counts = cur_counts.copy()
                new_counts[i] -= 1
                new_first = i if last == -1 else first
                count = dp(tuple(new_counts), i, new_first)
                if count >= k:
                    result.append(unique_chars[i])
                    cur_counts = new_counts
                    last = i
                    first = new_first
                    break
                else:
                    k -= count
        else:
            return None  # Should not reach here if total_valid >= k

    return ''.join(result)
