        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool, started: bool, prev2: int, prev1: int, pk: int, rem: int) -> int:
            if pk > peaks:
                return 0
            if pos == L:
                return 1 if (pk == peaks and rem == t) else 0

            limit = int(s[pos]) if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)

                if not started:
                    if d == 0:
                        total += dp(pos + 1, new_tight, False, -1, -1, pk, rem)
                    else:
                        new_rem = (rem * 10 + d) % q
                        total += dp(pos + 1, new_tight, True, -1, d, pk, new_rem)
                else:
                    new_rem = (rem * 10 + d) % q
                    if prev2 != -1:
                        new_pk = pk + 1 if (prev1 > prev2 and prev1 > d) else pk
                    else:
                        new_pk = pk
                    if new_pk > peaks:
                        continue
                    total += dp(pos + 1, new_tight, True, prev1, d, new_pk, new_rem)
            return total

        return dp(0, True, False, -1, -1, 0, 0)

    return count_up_to(hi) - count_up_to(lo - 1)
