from math import gcd


def spiral_position(n: int, first: int, grow: int, group: int, dirs: str) -> tuple[int, int]:
    if not dirs or any(c not in "NESW" for c in dirs):
        raise ValueError
    if first < 1 or grow < 0 or group < 1 or group > 50 or len(dirs) > 12 or n < 0:
        raise ValueError

    if n == 0:
        return (0, 0)

    L = len(dirs)
    G = group

    # Total steps used by m complete legs
    def total(m: int) -> int:
        if m == 0:
            return 0
        q = m // G
        r = m % G
        return G * (q * first + grow * q * (q - 1) // 2) + r * (first + grow * q)

    # Binary search: largest m in [0, n] with total(m) <= n
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if total(mid) <= n:
            lo = mid
        else:
            hi = mid - 1
    m_complete = lo
    remaining = n - total(m_complete)

    x = 0
    y = 0

    if m_complete > 0:
        q = m_complete // G
        r = m_complete % G

        T = L // gcd(L, G)  # period of the direction pattern across blocks

        # Precompute per-period direction sums
        dx_sums = [0] * T
        dy_sums = [0] * T
        for s in range(T):
            for i in range(G):
                d = dirs[(s + i) % L]
                if d == 'E':
                    dx_sums[s] += 1
                elif d == 'W':
                    dx_sums[s] -= 1
                elif d == 'N':
                    dy_sums[s] += 1
                elif d == 'S':
                    dy_sums[s] -= 1

        q0 = q // T
        q1 = q % T

        S0_dx = sum(dx_sums)
        S0_dy = sum(dy_sums)
        S1_dx = sum(j * dx_sums[j] for j in range(T))
        S1_dy = sum(j * dy_sums[j] for j in range(T))

        S0_dx_part = sum(dx_sums[:q1])
        S0_dy_part = sum(dy_sums[:q1])
        S1_dx_part = sum(j * dx_sums[j] for j in range(q1))
        S1_dy_part = sum(j * dy_sums[j] for j in range(q1))

        # sum_{b=0}^{q-1} dx_sums[b % T]
        sum_dx = q0 * S0_dx + S0_dx_part
        sum_dy = q0 * S0_dy + S0_dy_part

        # sum_{b=0}^{q-1} b * dx_sums[b % T]
        tri = T * q0 * (q0 - 1) // 2
        sum_b_dx = tri * S0_dx + q0 * S1_dx + q0 * T * S0_dx_part + S1_dx_part
        sum_b_dy = tri * S0_dy + q0 * S1_dy + q0 * T * S0_dy_part + S1_dy_part

        x += first * sum_dx + grow * sum_b_dx
        y += first * sum_dy + grow * sum_b_dy

        # Partial last block (r legs in block q)
        if r > 0:
            block_start = (q * G) % L
            dx_val = 0
            dy_val = 0
            for i in range(r):
                d = dirs[(block_start + i) % L]
                if d == 'E':
                    dx_val += 1
                elif d == 'W':
                    dx_val -= 1
                elif d == 'N':
                    dy_val += 1
                elif d == 'S':
                    dy_val -= 1
            length = first + grow * q
            x += length * dx_val
            y += length * dy_val

    # Steps into the (incomplete) next leg
    if remaining > 0:
        d = dirs[m_complete % L]
        if d == 'E':
            x += remaining
        elif d == 'W':
            x -= remaining
        elif d == 'N':
            y += remaining
        elif d == 'S':
            y -= remaining

    return (x, y)
