def courier_cost(n: int, roads: list[tuple[int, int, int]], depot: int,
                 jobs: list[tuple[int, int, int]], capacity: int) -> int | None:
    num_jobs = len(jobs)

    # A single parcel larger than the van can't be carried
    for _, _, s in jobs:
        if s > capacity:
            return None

    if num_jobs == 0:
        return 0

    # --- All-pairs shortest paths (Floyd-Warshall) ---
    INF = float("inf")
    sp = [[INF] * n for _ in range(n)]
    for i in range(n):
        sp[i][i] = 0
    for a, b, l in roads:
        if l < sp[a][b]:
            sp[a][b] = l
            sp[b][a] = l
    for mid in range(n):
        for i in range(n):
            if sp[i][mid] == INF:
                continue
            for j in range(n):
                if sp[mid][j] == INF:
                    continue
                nd = sp[i][mid] + sp[mid][j]
                if nd < sp[i][j]:
                    sp[i][j] = nd

    # Every junction that any job needs must be reachable from the depot
    needed = {depot}
    for p, d, _ in jobs:
        needed.add(p)
        needed.add(d)
    for node in needed:
        if sp[depot][node] == INF:
            return None

    # --- Dijkstra over (junction, job-state) ---
    # job-state: base-3 integer, digit j in {0,1,2}
    #   0 = not yet picked up, 1 = in van, 2 = delivered
    num_states = 3 ** num_jobs
    goal_state = num_states - 1          # all digits == 2

    # Pre-compute powers of 3
    p3 = [1] * num_jobs
    for j in range(1, num_jobs):
        p3[j] = p3[j - 1] * 3

    # dist_table[node][state] = best cost seen
    dist_table = [[INF] * num_states for _ in range(n)]
    dist_table[depot][0] = 0

    heap = [(0, depot, 0)]   # (cost, node, state)

    while heap:
        d, node, state = heapq.heappop(heap)
        if d > dist_table[node][state]:
            continue

        # Goal reached?
        if node == depot and state == goal_state:
            return d

        # --- Move to another junction (no loading/unloading) ---
        for v in range(n):
            if v == node:
                continue
            w = sp[node][v]
            if w == INF:
                continue
            nd = d + w
            if nd < dist_table[v][state]:
                dist_table[v][state] = nd
                heapq.heappush(heap, (nd, v, state))

        # --- Load / unload at this junction (zero cost) ---
        # Extract the base-3 digits of `state`
        digits = [0] * num_jobs
        tmp = state
        for j in range(num_jobs):
            digits[j] = tmp % 3
            tmp //= 3

        # For each job, the set of new digits it can have at this node
        options = []
        for j in range(num_jobs):
            cur = digits[j]
            p, df, _ = jobs[j]
            if cur == 0:
                if p == node:
                    if df == node:
                        options.append([0, 1, 2])   # stay, pick+deliver, pick
                    else:
                        options.append([0, 1])       # stay or pick up
                else:
                    options.append([0])
            elif cur == 1:
                if df == node:
                    options.append([1, 2])           # stay or deliver
                else:
                    options.append([1])
            else:   # cur == 2
                options.append([2])

        for combo in product(*options):
            # Build new state & check capacity
            new_state = 0
            load = 0
            for j, nd_digit in enumerate(combo):
                new_state |= nd_digit * p3[j]
                if nd_digit == 1:
                    load += jobs[j][2]
            if new_state == state or load > capacity:
                continue
            if d < dist_table[node][new_state]:
                dist_table[node][new_state] = d
                heapq.heappush(heap, (d, node, new_state))

    return None
```

**How it works**

* **Shortest paths:** Floyd–Warshall (O(n³), n ≤ 60) gives the minimum driving distance between every pair of junctions.
* **Connectivity check:** if any junction involved in a job is unreachable from the depot, return `None`.
* **State space:** each job is in one of three statuses (not picked / in van / delivered), encoded as a base-3 digit. With ≤ 6 jobs there are 3⁶ = 729 job-state combinations, and 60 junctions → **~43 740 total Dijkstra states**.
* **Transitions from (node, job_state):**
  * **Move** to any other junction v – cost = sp[node][v], job state unchanged.
  * **Load / unload** at the current junction (zero cost) – for every job that can be picked up (pickup == node, state 0) or delivered (dropoff == node, state 1), we pick a new digit (stay / pick / deliver), enumerate all combinations via `itertools.product`, and keep only those whose resulting van-load ≤ capacity.
* **Goal:** reach the depot with all digits equal to 2.

This is a proper Dijkstra on a finite graph rather than enumerating 12! permutations, so it runs quickly even at the upper limits.

