from collections import OrderedDict


class PinCache:
    def __init__(self, max_items: int, max_weight: int):
        self.max_items = max_items
        self.max_weight = max_weight
        self._cache: "OrderedDict[str, tuple]" = OrderedDict()
        self._total_weight: int = 0

    def _evict(self, exclude_key: str | None = None) -> list:
        evicted: list[str] = []
        while (
            len(self._cache) > self.max_items
            or self._total_weight > self.max_weight
        ):
            cold_cands: list[str] = []
            warm_cands: list[str] = []
            for k, entry in self._cache.items():
                if k == exclude_key:
                    continue
                if entry[2]:  # pinned
                    continue
                if entry[3] == "COLD":
                    cold_cands.append(k)
                else:
                    warm_cands.append(k)

            candidates = cold_cands + warm_cands
            if not candidates:
                raise OverflowError("Cannot meet cache limits with pinned entries.")

            evict_key = candidates[0]
            evicted.append(evict_key)
            self._total_weight -= self._cache.pop(evict_key)[1]

        return evicted

    def put(self, key, value, weight: int = 1) -> list:
        if weight < 1 or weight > self.max_weight:
            raise ValueError(f"Weight {weight} must satisfy 1 <= w <= max_weight({self.max_weight}).")

        snapshot = {k: tuple(v) for k, v in self._cache.items()}
        snapshot_weight = self._total_weight

        try:
            if key in self._cache:
                _, old_weight, pinned, _ = self._cache[key]
                self._cache[key] = (value, weight, pinned, "COLD")
                self._total_weight += weight - old_weight
                self._cache.move_to_end(key)
            else:
                self._cache[key] = (value, weight, False, "COLD")
                self._total_weight += weight

            return self._evict(exclude_key=key)
        except OverflowError:
            self._cache = OrderedDict(snapshot)
            self._total_weight = snapshot_weight
            raise

    def get(self, key, default=None):
        if key in self._cache:
            value, weight, pinned, _ = self._cache[key]
            self._cache[key] = (value, weight, pinned, "WARM")
            self._cache.move_to_end(key)
            return value
        return default

    def peek(self, key, default=None):
        if key in self._cache:
            return self._cache[key][0]
        return default

    def pin(self, key) -> bool:
        if key not in self._cache:
            return False
        value, weight, _, temp = self._cache[key]
        self._cache[key] = (value, weight, True, temp)
        return True

    def unpin(self, key) -> bool:
        if key not in self._cache:
            return False
        value, weight, _, temp = self._cache[key]
        self._cache[key] = (value, weight, False, temp)
        return True

    def drop(self, key) -> bool:
        if key not in self._cache:
            return False
        self._total_weight -= self._cache.pop(key)[1]
        return True

    def resize(self, max_items: int, max_weight: int) -> list:
        old_items = self.max_items
        old_weight = self.max_weight
        snapshot = {k: tuple(v) for k, v in self._cache.items()}
        snapshot_weight = self._total_weight

        try:
            self.max_items = max_items
            self.max_weight = max_weight
            return self._evict(exclude_key=None)
        except OverflowError:
            self.max_items = old_items
            self.max_weight = old_weight
            self._cache = OrderedDict(snapshot)
            self._total_weight = snapshot_weight
            raise

    def keys(self) -> list:
        return list(self._cache.keys())

    def stats(self) -> tuple[int, int]:
        return (len(self._cache), self._total_weight)
