class Timeline:
    def __init__(self) -> None:
        self._revisions: dict[int, str] = {0: ""}
        self._parents: dict[int, int | None] = {0: None}
        self._children: dict[int, list[int]] = {0: []}
        self._preferred: dict[int, int | None] = {0: None}
        self._current: int = 0
        self._next_id: int = 1

    def _update_preferred_path(self) -> None:
        """For every revision on the path from root to current (excluding root),
        mark it as the preferred child of its parent."""
        node = self._current
        while node is not None:
            node = self._parents[node]
        # Walk down: actually we need the path from root to current
        # Re-walk collecting the path
        path = []
        node = self._current
        while node is not None:
            path.append(node)
            node = self._parents[node]
        # path is [current, ..., 1, 0]
        for r in path:
            if r == 0:
                continue
            parent = self._parents[r]
            if parent is not None:
                self._preferred[parent] = r

    def _is_ancestor_or_self(self, ancestor: int, node: int) -> bool:
        current = node
        while current is not None:
            if current == ancestor:
                return True
            current = self._parents[current]
        return False

    def _subtree(self, root_id: int) -> list[int]:
        result = [root_id]
        stack = [root_id]
        while stack:
            node = stack.pop()
            for child in self._children[node]:
                result.append(child)
                stack.append(child)
        return result

    def write(self, s: str) -> int:
        new_id = self._next_id
        self._next_id += 1
        self._parents[new_id] = self._current
        self._children[self._current].append(new_id)
        self._children[new_id] = []
        self._preferred[new_id] = None
        self._revisions[new_id] = self._revisions[self._current] + s
        self._current = new_id
        self._update_preferred_path()
        return new_id

    def erase(self, n: int) -> int:
        if n < 0:
            raise ValueError("n must be non-negative")
        cur_text = self._revisions[self._current]
        if n > len(cur_text):
            raise ValueError("n exceeds the length of the current text")
        new_id = self._next_id
        self._next_id += 1
        self._parents[new_id] = self._current
        self._children[self._current].append(new_id)
        self._children[new_id] = []
        self._preferred[new_id] = None
        self._revisions[new_id] = cur_text[:len(cur_text) - n]
        self._current = new_id
        self._update_preferred_path()
        return new_id

    def undo(self) -> bool:
        parent = self._parents[self._current]
        if parent is None:
            return False
        self._current = parent
        self._update_preferred_path()
        return True

    def redo(self) -> bool:
        pref = self._preferred[self._current]
        if pref is None:
            return False
        self._current = pref
        self._update_preferred_path()
        return True

    def checkout(self, rev: int) -> None:
        if rev not in self._parents:
            raise KeyError(f"revision {rev} not found")
        self._current = rev
        self._update_preferred_path()

    def text(self) -> str:
        return self._revisions[self._current]

    def current(self) -> int:
        return self._current

    def parent(self, rev: int) -> int | None:
        if rev not in self._parents:
            raise KeyError(f"revision {rev} not found")
        return self._parents[rev]

    def children(self, rev: int) -> list[int]:
        if rev not in self._children:
            raise KeyError(f"revision {rev} not found")
        return list(self._children[rev])

    def log(self) -> list[int]:
        path = []
        node = self._current
        while node is not None:
            path.append(node)
            node = self._parents[node]
        return path[::-1]

    def distance(self, a: int, b: int) -> tuple[int, int]:
        if a not in self._parents:
            raise KeyError(f"revision {a} not found")
        if b not in self._parents:
            raise KeyError(f"revision {b} not found")

        chain_a: set[int] = set()
        node = a
        while node is not None:
            chain_a.add(node)
            node = self._parents[node]

        node = b
        while node not in chain_a:
            node = self._parents[node]
        lca = node

        ups = 0
        node = a
        while node != lca:
            node = self._parents[node]
            ups += 1

        downs = 0
        node = b
        while node != lca:
            node = self._parents[node]
            downs += 1

        return (ups, downs)

    def prune(self, rev: int) -> int:
        if rev not in self._parents:
            raise KeyError(f"revision {rev} not found")
        if rev == 0:
            raise ValueError("cannot prune the root")
        if self._is_ancestor_or_self(rev, self._current):
            raise ValueError("cannot prune the current revision or its descendants")

        subtree = self._subtree(rev)
        count = len(subtree)

        parent_id = self._parents[rev]
        if parent_id is not None:
            self._children[parent_id].remove(rev)
            if self._preferred[parent_id] == rev:
                remaining = self._children[parent_id]
                self._preferred[parent_id] = max(remaining) if remaining else None

        for node in subtree:
            del self._parents[node]
            del self._children[node]
            del self._preferred[node]
            del self._revisions[node]

        return count
